function enforceVisible(data){let note=$('legacySourceNotice');if(!note){note=text('p','');note.id='legacySourceNotice';note.setAttribute('role','status');$('todayTable').before(note)}note.textContent=data?.snapshot&&data.snapshot.sourceType!=='madrasati'?'هذا سجل سابق للعرض فقط. مدرستي هي المصدر الوحيد للتشغيل؛ حمّل جدولها ثم اختر حفظ السابق أو استبداله.':'';return true}
async function today(refresh=true){const date=model.day();if(!dates.includes(date)){if(!enforceVisible(null))return;renderTable('todayTable',null);$('dayTitle').textContent=date;return}const data=await day(date,refresh);if(!enforceVisible(data))return;selectedDay=data;const schedule={...model.defaultSchedule,...data.snapshot.scheduleSettings,...data.reportSchedule};$('dayTitle').textContent='تاريخ الجدول: '+data.snapshot.date+(data.snapshot.sourceScheduleDate?' · جدول '+(data.snapshot.sourceType==='naqar'?'نقار':'مدرستي')+' '+data.snapshot.sourceScheduleDate:data.snapshot.sourceType==='naqar'?' · المصدر نقار':'')+' · بداية الحصص '+schedule.manualStart+' · مدة الحصة '+schedule.periodDuration+' دقيقة · الفاصل '+schedule.manualGapMinutes+' دقيقة';renderTable('todayTable',data)}
async function connect(){endpoint=$('endpoint').value.trim();readerKey=$('readerKey').value.trim();if(!/^https:\/\/script\.google\.com\/macros\/s\/[A-Za-z0-9_-]+\/exec$/.test(endpoint))throw new Error('رابط خدمة الرصد غير صالح');const result=await api('dates');publicAccess=result.authMode==='public';dates=result.dates;localStorage.setItem('mirsad-monitor-url',endpoint);$('archiveDate').replaceChildren(text('option','اختر تاريخًا'));$('archiveDate').firstChild.value='';for(const date of dates){const option=text('option',date);option.value=date;$('archiveDate').append(option)}await today();if(readerKey&&!publicAccess)localStorage.setItem(SAVED_READER_KEY,readerKey);if(result.authMode==='site-password')localStorage.setItem(ARCHIVE_PASSWORD_KEY,readerKey);connectionState(true);status(publicAccess?'السجل والصور متاحان لأي شخص لديه الرابط':'تم الاتصال بالسجل الخاص؛ الدخول محفوظ على هذا الجهاز');if(currentView!=='today')await loadView(currentView)}
