async function loadArchive(){const date=$('archiveDate').value;if(!date){emptyView('archiveTable','لا توجد أيام محفوظة في خدمة الرصد المتصلة. حمّل جدول الرصد من الخطوة 1 ثم شغّله من الإضافة.');return}emptyView('archiveTable','جارٍ تحميل أرشيف '+date+'…');try{const data=await day(date,true);$('archiveTitle').textContent='جدول '+data.snapshot.date;renderTable('archiveTable',data)}catch(e){emptyView('archiveTable','تعذر تحميل الأرشيف: '+e.message);throw e}}
