async function loadView(view){
 if(view==='reports'){await loadTeacherReports();return}
 const target=view==='today'?'todayTable':view==='archive'?'archiveTable':'chart';
 if(!readerKey&&!publicAccess){emptyView(target,'سجّل الدخول بكلمة مرور مرصاد لعرض '+(view==='archive'?'الأرشيف':view==='stats'?'الإحصائية':'حضور وغياب اليوم')+'.');$('connect').hidden=false;status('يلزم تسجيل الدخول لقراءة النتائج المحفوظة');return}
 try{if(view==='today'){emptyView(target,'جارٍ تحميل حضور وغياب اليوم…');await today(true)}else if(view==='archive'){if(!$('archiveDate').value&&dates.length)$('archiveDate').value=dates[0];await loadArchive()}else await $('loadStats').onclick()}catch(e){emptyView(target,'تعذر تحميل البيانات: '+e.message);status(e.message,true)}
}
