function renderStats(stats,days){const root=$('statsTable');root.replaceChildren();const table=document.createElement('table'),thead=document.createElement('thead'),hr=document.createElement('tr');['المعلم','الحصص المقررة','غياب الحصص','غياب يوم كامل','حضور الحصص','نسبة الغياب','غير محسوم','حضور متأخر','حضور جزئي','غياب جزئي'].forEach(x=>hr.append(text('th',x)));thead.append(hr);table.append(thead);const body=document.createElement('tbody');for(const r of stats){const row=document.createElement('tr'),td=document.createElement('td'),button=text('button',r.name);button.onclick=()=>{const cells=days.flatMap(d=>model.cells(d).filter(c=>c.teacherId===r.id).map(c=>({...c,date:d.snapshot.date})));$('detailTitle').textContent='سجل '+r.name;const target=$('detailBody');target.replaceChildren();for(const c of cells){const b=text('button',c.date+' — الحصة '+c.period+' — '+(c.reset?'لم يبدأ الرصد':stateLabel[c.displayState||c.state]));b.onclick=()=>{$('details').close();detail(c,c.date)};target.append(b)}$('details').showModal()};td.append(button);row.append(td);[r.scheduled,r.absentLessons,r.absentDays,r.present,r.percent+'%',r.unknown,r.late,r.partial,r.partialAbsence].forEach(v=>row.append(text('td',v)));body.append(row)}table.append(body);root.append(table);
summaryCards('statsSummary',[['غياب الحصص',stats.reduce((s,r)=>s+r.absentLessons,0),'danger'],['غياب يوم كامل',stats.reduce((s,r)=>s+r.absentDays,0),'danger'],['حضور الحصص',stats.reduce((s,r)=>s+r.present,0),'success'],['غير محسوم',stats.reduce((s,r)=>s+r.unknown,0)],['غياب جزئي',stats.reduce((s,r)=>s+r.partialAbsence,0),'warning']]);renderChart(stats)}
function renderChart(rows){
 const root=$('chart');root.replaceChildren();if(!rows.length){root.append(text('p','لا توجد سجلات في الفترة المحددة'));return}
 const series=[['absentLessons','#b63c48','غياب الحصص'],['absentDays','#173f53','غياب يوم كامل'],['present','#147356','حضور الحصص'],['unknown','#d18b19','غير محسوم'],['partialAbsence','#ed8a19','غياب جزئي']];
 const legend=text('div','');legend.className='chart-legend';for(const [key,color,label] of series){const item=text('span',label),dot=text('i','');dot.style.backgroundColor=color;dot.setAttribute('aria-hidden','true');item.prepend(dot);legend.append(item)}root.append(legend);
 const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg'),width=Math.max(1000,rows.length*180);svg.setAttribute('width',width);svg.setAttribute('height',360);svg.setAttribute('role','img');svg.setAttribute('aria-label','غياب الحصص وغياب يوم كامل وحضور الحصص وغير محسوم لكل معلم');
 const max=Math.max(1,...rows.flatMap(row=>series.map(([key])=>row[key]||0)));
 rows.forEach((row,i)=>{const x=35+i*180;
  series.forEach(([key,color,label],j)=>{const n=row[key]||0,rect=document.createElementNS(ns,'rect'),h=n/max*180;for(const [k,v] of Object.entries({x:x+j*27,y:220-h,width:21,height:h,fill:color,'data-series':key,'data-value':n}))rect.setAttribute(k,v);const title=document.createElementNS(ns,'title');title.textContent=row.name+' — '+label+': '+n;rect.append(title);svg.append(rect);const number=document.createElementNS(ns,'text');number.setAttribute('x',x+j*27+10.5);number.setAttribute('y',210-h);number.setAttribute('text-anchor','middle');number.setAttribute('font-size','12');number.textContent=n;svg.append(number)});
  const label=document.createElementNS(ns,'text');label.setAttribute('transform','translate('+(x+50)+',250) rotate(-30)');label.setAttribute('text-anchor','end');label.setAttribute('font-size','12');label.textContent=row.name;svg.append(label)
 });root.append(svg)
}

$('loadStats').onclick=async()=>{const b=$('loadStats');b.disabled=true;try{if(!readerKey&&!publicAccess){emptyView('chart','سجّل الدخول بكلمة مرور مرصاد لعرض الإحصائية.');return}emptyView('chart','جارٍ تحميل الإحصائية…');const from=$('fromDate').value,to=$('toDate').value;if(!from||!to||from>to)throw new Error('حدد فترة صحيحة');const selected=dates.filter(d=>d>=from&&d<=to),days=[];for(const date of selected){status('تحميل إحصائية '+date);days.push(await day(date,true))}renderStats(model.stats(days),days);status('عُرضت إحصائية '+days.length+' يومًا')}catch(e){emptyView('chart','تعذر تحميل الإحصائية: '+e.message);status(e.message,true)}finally{b.disabled=false}};

function applyScanHighlight(){
 const root=$('todayTable');for(const row of root.querySelectorAll('.scanning-row'))row.classList.remove('scanning-row');for(const cell of root.querySelectorAll('.scanning-cell')){cell.classList.remove('scanning-cell');cell.removeAttribute('aria-busy')}
 const remoteFresh=remoteHeartbeat&&Date.now()+remoteServerOffset-remoteHeartbeat.at<=75000&&Date.now()+remoteServerOffset>=remoteHeartbeat.at-10000;
 for(const el of root.querySelectorAll('.round-active-cell,.round-active-heading'))el.classList.remove('round-active-cell','round-active-heading');
 const roundPeriod=activeScan?.date===model.day()?activeScan.period:remoteFresh&&remoteHeartbeat.running&&remoteHeartbeat.phase==='scanning'?remoteHeartbeat.period:null;
 if(roundPeriod&&!model.isExcludedPeriod(model.day(),roundPeriod,renderedDays.get(model.day())?.snapshot)&&root.dataset.date===model.day()){for(const td of root.querySelectorAll('td[data-period="'+roundPeriod+'"]:not(.no-lesson)'))td.classList.add('round-active-cell');const th=root.querySelectorAll('thead th')[roundPeriod];if(th)th.classList.add('round-active-heading')}
 const active=activeScan?.date===model.day()&&activeScan.period&&!model.isExcludedPeriod(model.day(),activeScan.period,renderedDays.get(model.day())?.snapshot)?activeScan:null,bar=$('scanActivity');bar.classList.toggle('is-scanning',!!active);
 $('scanActivityText').textContent=active?'جارٍ فحص: '+active.teacher+' — الحصة '+active.period+' — الدورة '+active.cycle:'لا يوجد فحص جارٍ';
 if(!active||root.dataset.date!==active.date)return;
 const rows=[...root.querySelectorAll('tbody tr')].filter(row=>active.teacherId?row.dataset.teacherId===active.teacherId:model.normalize(row.dataset.teacherName)===model.normalize(active.teacher));
 if(rows.length!==1)return;const row=rows[0];row.classList.add('scanning-row');const cell=[...row.querySelectorAll('td')].find(td=>Number(td.dataset.period)===Number(active.period));if(cell){cell.classList.add('scanning-cell');cell.setAttribute('aria-busy','true')}
 if($('followScan').checked&&lastFollowedScan!==active.scanId&&!$('today').hidden&&!document.hidden&&!$('details').open){lastFollowedScan=active.scanId;row.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'})}
}
window.addEventListener('mirsad-remote-day',event=>{
 const value=event.detail;if(!value?.snapshot||value.snapshot.date!==model.day())return;
 remoteHeartbeat=value.heartbeat||null;remoteServerOffset=Number.isFinite(value.serverTime)?value.serverTime-Date.now():0;
 MirsadLessonClock.setHeartbeat?.(remoteHeartbeat,value.serverTime);
 const fresh=remoteHeartbeat&&Date.now()+remoteServerOffset-remoteHeartbeat.at<=75000&&Date.now()+remoteServerOffset>=remoteHeartbeat.at-10000;
 if(Date.now()-lastLocalActivityContact>15000){const a=fresh&&remoteHeartbeat.running&&remoteHeartbeat.phase==='scanning'?remoteHeartbeat.activity:null;activeScan=a?{...a,active:true}:null;lastActivityContact=Date.now()}
 const signature=JSON.stringify([value.snapshot,value.records,value.adjustments,model.cells(value).map(c=>c.state)]);
 cache.set(value.snapshot.date,value);renderedDays.set(value.snapshot.date,value);
 if(signature!==remoteTableSignature){remoteTableSignature=signature;if($('todayTable').dataset.date===value.snapshot.date)renderTable('todayTable',value);
  if(currentView==='stats'){const selected=dates.filter(d=>d>=$('fromDate').value&&d<=$('toDate').value),days=selected.map(d=>cache.get(d)).filter(Boolean);if(days.length===selected.length)renderStats(model.stats(days),days)}
 }
 applyScanHighlight();
});
window.addEventListener('mirsad-remote-disconnected',()=>{remoteHeartbeat=null;MirsadLessonClock.setHeartbeat?.(null);if(Date.now()-lastLocalActivityContact>15000)activeScan=null;applyScanHighlight()});
$('followScan').onchange=()=>{lastFollowedScan='';applyScanHighlight()};
setInterval(()=>{if(remoteHeartbeat&&Date.now()+remoteServerOffset-remoteHeartbeat.at>75000){remoteHeartbeat=null;if(Date.now()-lastLocalActivityContact>15000)activeScan=null;applyScanHighlight()}if(activeScan&&Date.now()-lastActivityContact>25000){activeScan=null;applyScanHighlight();$('scanActivityText').textContent='تعذر الاتصال بالإضافة — أعد التحقق من التشغيل'}},5000);

async function saveManualLink(payload){
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),25000);
 let result;try{result=await api('manualLessonLink',{date:payload.date,teacherId:payload.teacherId,period:payload.period,url:payload.url,expectedUrl:payload.expectedUrl,expectedRevision:payload.expectedRevision,requestId:crypto.randomUUID()},{signal:controller.signal})}catch(error){if(/صلاحية القراءة لا تسمح بالرفع|تعديل الرابط خاص بإضافة/.test(error.message))throw new Error('حفظ الرابط من الجوال يحتاج نشر سكريبت مرصاد 0.6.70 كإصدار جديد في مشروع قوقل الحالي، ثم تحديث الصفحة');if(error.name==='AbortError'||/fetch|network|load failed/i.test(error.message))throw new Error('لم يتأكد حفظ الرابط بسبب الاتصال؛ حدّث الحصة للتحقق من الرابط المحفوظ ثم أعد المحاولة إذا لزم');throw error}finally{clearTimeout(timer)}
 const row=result.snapshot?.lessons?.find(l=>l.teacherId===payload.teacherId&&Number(l.period)===Number(payload.period));
 if(!result.saved||result.snapshot?.date!==payload.date||!row||(row.url||'')!==(payload.url||''))throw new Error('لم يتأكد حفظ الرابط في جدول الحصة؛ حدّث سكربت مرصاد ثم أعد المحاولة');
 cache.delete(payload.date);extensionMessage('remoteLinksUpdated',{date:payload.date});return result;
}
let bridgeTimer;
