window.addEventListener('message',event=>{if(event.source!==window||event.origin!==location.origin||event.data?.source!=='mirsad-monitor-extension')return;const r=event.data.payload;if(event.data.type==='purgedDay')status(r?.ok?'أُلغي جدول الإضافة القديم؛ انقل الجدول المطلوب ثم ابدأ الرصد.':r?.error||'لم يتأكد تحديث جدول الإضافة؛ حدّثها وأعد تجهيز اليوم.',!r?.ok);if(event.data.type==='activity'){lastLocalActivityContact=Date.now();lastActivityContact=Date.now();activeScan=r?.ok&&r.activity?.active?r.activity:null;applyScanHighlight()}if(event.data.type==='changed')void refreshRemote();if(event.data.type==='state')extensionReady=!!r?.ok;});
