let refreshingRemote=false;
async function refreshRemote(){if((!readerKey&&!publicAccess)||refreshingRemote)return;refreshingRemote=true;try{const result=await api('dates');dates=result.dates;const select=$('archiveDate'),value=select.value;if(JSON.stringify([...select.options].map(o=>o.value).filter(Boolean))!==JSON.stringify(dates)){select.replaceChildren(text('option','اختر تاريخًا'));select.firstChild.value='';for(const date of dates){const option=text('option',date);option.value=date;select.append(option)}if(dates.includes(value))select.value=value;}await today(true);if(currentView==='archive'&&$('archiveDate').value)await loadArchive();connectionState(true);status('آخر تحديث للرصد: '+new Date().toLocaleTimeString('ar-SA',{timeZone:'Asia/Riyadh'}))}catch(e){if(e.code==='unauthorized')forgetSavedConnection();status('تعذر تحديث الرصد: '+e.message,true)}finally{refreshingRemote=false}}
