async function restoreSavedConnection(){const saved=localStorage.getItem(ARCHIVE_PASSWORD_KEY)||localStorage.getItem(SAVED_READER_KEY);if(!saved){publicAccess=true;try{await connect()}catch(error){publicAccess=false;connectionState(false);if(error.code!=='unauthorized')status('تعذر الاتصال بخدمة الرصد: '+error.message,true)}return;}$('readerKey').value=saved;connectionState(true);status('جارٍ استعادة الاتصال المحفوظ…');try{await connect()}catch(error){if(error.code==='unauthorized'){forgetSavedConnection();status('رمز الاطلاع المحفوظ لم يعد صالحًا؛ أدخل كلمة مرور مرصاد الحالية؛ وتأكد أن المشرف ضبط MONITOR_SITE_PASSWORD في خدمة الرصد',true)}else status('الدخول محفوظ؛ تعذر الاتصال حاليًا وستُعاد المحاولة تلقائيًا: '+error.message,true)}}
