function teacherDailyCard(report){const card=text('article','');card.className='teacher-report-card';card.append(text('h3','مساءلة يوم '+report.date),text('p',report.reports.map(r=>MirsadTeacherReport.typeLabel[r.type]).join(' · ')),text('p','الحصص: '+[...new Set(report.lessons.map(c=>c.period))].sort((a,b)=>a-b).join('، ')));const actions=text('div','');actions.className='teacher-report-downloads';for(const format of ['pdf','word']){const download=text('button',format==='pdf'?'تحميل PDF':'تحميل Word');download.type='button';download.dataset.format=format;download.onclick=async()=>{download.disabled=true;try{const fresh=await day(report.date,true),latest=availableLetters(fresh).find(r=>r.id===report.id);if(!latest)throw new Error('تغيّرت الحالة المعتمدة؛ لا توجد حالات تستدعي طلب إفادة لهذا اليوم.');const school=$('teacherReportSchool').value.trim();if(format==='pdf')await MirsadTeacherReportPdf.download(latest,school);else await MirsadTeacherReport.download(latest,school);$('teacherReportFeedback').textContent='تم تجهيز مساءلة يوم '+report.date+' للمعلم '+latest.name}catch(e){$('teacherReportFeedback').textContent=e.message}finally{download.disabled=false}};actions.append(download)}const remove=text('button','🗑 حذف الخطاب');remove.type='button';remove.className='delete-letter';remove.setAttribute('aria-label','حذف خطاب '+report.name+' ليوم '+report.date);remove.onclick=async()=>{if(!confirm('حذف خطاب '+report.name+' ليوم '+report.date+' من قائمة هذا المتصفح؟ الحضور والصور لا تتأثر.'))return;try{MirsadLetterList.remove([report],endpoint,report.date);await loadTeacherReports();$('teacherReportFeedback').textContent='حُذف الخطاب من القائمة؛ الحضور والصور محفوظان'}catch(e){$('teacherReportFeedback').textContent='تعذر حذف الخطاب: '+e.message}};actions.append(remove);card.append(actions);return card}
let teacherReportLoad=0,teacherReportDay=null,bulkReportsBusy=false;
function updateReportReadiness(){if($('teacherReportScope').value==='today'&&$('teacherReportDate').value!==model.day()){$('teacherReportDate').value=model.day();teacherReportDay=null;$('teacherReportList').replaceChildren();$('teacherReportFeedback').textContent='بدأ يوم جديد؛ لا تدخل خطابات الأمس ضمن تجميع اليوم';void loadTeacherReports()}const data=teacherReportDay?.snapshot.date===$('teacherReportDate').value?teacherReportDay:null,ended=data&&MirsadTeacherReport.ready(data,model),available=!!data&&availableLetters(data).length>0;const badge=$('dailyReportsReady');badge.textContent=!available&&MirsadLetterList.count(endpoint,$('teacherReportDate').value)?'الخطابات محذوفة من القائمة':ended?(available?'جاهز · نهاية اليوم':'اكتمل اليوم · لا خطابات مستحقة'):available?'متاح الآن · اليوم مستمر':'قيد الرصد';$('reports').dataset.dayComplete=String(!!ended);$('deleteAllLetters').disabled=!available||bulkReportsBusy;$('restoreLetters').hidden=!MirsadLetterList.count(endpoint,$('teacherReportDate').value);badge.className=available?'daily-reports-ready':'daily-reports-pending';for(const id of ['downloadDailyReports','downloadDailyReportsWord']){$(id).disabled=!available||bulkReportsBusy;$(id).textContent=(ended?'تحميل جميع خطابات اليوم ':'تحميل جميع الخطابات المتاحة ')+(id==='downloadDailyReports'?'PDF':'Word')}return available}

setInterval(()=>{if(!$('reports').hidden)updateReportReadiness()},1000);

async function loadTeacherReports(){const load=++teacherReportLoad;const button=$('loadTeacherReports'),list=$('teacherReportList'),feedback=$('teacherReportFeedback'),opened=new Set([...list.querySelectorAll('details[open]')].map(e=>e.dataset.teacherId));button.disabled=true;teacherReportDay=null;updateReportReadiness();feedback.textContent='جارٍ ترتيب تقارير المعلمين…';try{if(!readerKey&&!publicAccess)throw new Error('اتصل بسجل الرصد أولًا');const date=$('teacherReportDate').value;if(!/^\d{4}-\d{2}-\d{2}$/.test(date))throw new Error('حدد تاريخ التقرير');const savedDate=dates.includes(date)?date:null;if(!savedDate){list.replaceChildren();feedback.textContent='لا توجد تقارير محفوظة بتاريخ '+date;return}const data=await day(savedDate,true),reports=savedDate===date?availableLetters(data):[];if(load!==teacherReportLoad)return;teacherReportDay=savedDate===date?data:null;updateReportReadiness();list.replaceChildren();for(const teacher of reports.slice().sort((a,b)=>a.name.localeCompare(b.name,'ar'))){const folder=text('details','');folder.className='teacher-report-folder';folder.dataset.teacherId=teacher.id;const summary=text('summary',''),name=text('strong',teacher.name),report=reports.find(r=>r.id===teacher.id);summary.append(name,text('span',report?'يوجد خطاب لهذا اليوم':'تقارير المعلم'));const contents=text('div','');contents.className='teacher-report-contents';if(report)contents.append(teacherDailyCard(report));else contents.append(text('p','لا توجد حالات تستدعي طلب إفادة بتاريخ '+date));folder.append(summary,contents);list.append(folder);if(report||opened.has(teacher.id))folder.open=true}feedback.textContent=reports.length?'خطابات المساءلة اليومية · '+date+': '+reports.length:'لا توجد خطابات جاهزة لهذا اليوم · '+date}catch(e){if(load===teacherReportLoad){list.replaceChildren();feedback.textContent=e.message}}finally{if(load===teacherReportLoad)button.disabled=false}}
$('deleteAllLetters').onclick=async()=>{const date=$('teacherReportDate').value,data=teacherReportDay;if(!data||data.snapshot.date!==date)return;const letters=availableLetters(data);if(!letters.length||!confirm('حذف '+letters.length+' خطابًا معروضًا ليوم '+date+' من قائمة هذا المتصفح؟ الحضور والصور لا تتأثر.'))return;try{MirsadLetterList.remove(letters,endpoint,date);await loadTeacherReports();$('teacherReportFeedback').textContent='حُذفت '+letters.length+' خطابات من القائمة ليوم '+date+'؛ الحضور والصور محفوظان'}catch(e){$('teacherReportFeedback').textContent='تعذر حذف الخطابات: '+e.message}};
$('restoreLetters').onclick=async()=>{try{MirsadLetterList.restore(endpoint,$('teacherReportDate').value);await loadTeacherReports()}catch(e){$('teacherReportFeedback').textContent=e.message}};
window.addEventListener('storage',event=>{if(event.key?.startsWith('mirsad-letter-deletions-v1:')&&!$('reports').hidden)void loadTeacherReports()});
$('loadTeacherReports').onclick=loadTeacherReports;
$('teacherReportDate').onchange=loadTeacherReports;
$('teacherReportScope').onchange=async()=>{const previous=$('teacherReportScope').value==='previous';$('teacherReportDateLabel').hidden=!previous;if(previous){const last=dates.find(d=>d<model.day());const yesterday=new Date(Date.now()-86400000);$('teacherReportDate').max=model.day(yesterday);$('teacherReportDate').value=last||model.day(yesterday)}else{$('teacherReportDate').removeAttribute('max');$('teacherReportDate').value=model.day()}await loadTeacherReports()};

// Public sharing does not require an administration login. Restricted links remain server-issued.
let teacherShareCache=null;
async function publicTeacherLink(){
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);
 try{const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:'teachersLive',audience:'teachers'}),signal:controller.signal});if(!response.ok)throw new Error('تعذر تجهيز رابط اللايف؛ أعد المحاولة');const value=await response.json();if(!value.ok||value.feed!=='teachers-live-v1'||value.source!=='official')throw new Error('رابط المشاهدة مقيّد؛ سجّل دخول الإدارة لنسخ الرابط المصرّح');return new URL('/teachers-live.html',location.origin).href}finally{clearTimeout(timer)}
}
function prepareTeacherLink(){
 const scope=endpoint+'|'+readerKey+'|'+EXPERIMENT_ID;
 if(teacherShareCache?.scope===scope)return teacherShareCache.promise;
 const promise=(async()=>{let href;if(readerKey){try{href=(await api('teacherLink')).url}catch(error){if(EXPERIMENT_ID)throw error;href=await publicTeacherLink()}}else{if(EXPERIMENT_ID)throw new Error('سجّل دخول الإدارة لنسخ رابط هذه التجربة');href=await publicTeacherLink()}const url=new URL(href);if(url.origin!==location.origin||url.pathname!=='/teachers-live.html'||(EXPERIMENT_ID&&url.searchParams.get('experiment')!==EXPERIMENT_ID)||(!EXPERIMENT_ID&&url.searchParams.has('experiment')))throw new Error('رابط المشاهدة غير صالح');return url.href})();
 teacherShareCache={scope,promise};promise.catch(()=>{if(teacherShareCache?.promise===promise)teacherShareCache=null});return promise;
}
async function copyPreparedTeacherLink(){
 const input=$('teacherShareUrl');if(!input.value)return false;
 try{await navigator.clipboard.writeText(input.value)}catch{input.focus();input.select();input.setSelectionRange(0,input.value.length);let copied=false;try{copied=document.execCommand('copy')}catch{}if(!copied){$('teacherShareFeedback').textContent='الرابط محدد؛ اضغط مطولًا واختر نسخ، أو اضغط Ctrl+C';return false}}
 $('teacherLinkFeedback').textContent='نُسخ رابط اللايف للمعلمين';$('teacherShareFeedback').textContent='نُسخ الرابط';if($('teacherShareDialog').open)$('teacherShareDialog').close();return true;
}
$('copyTeachersLiveLink').onclick=async()=>{const button=$('copyTeachersLiveLink');button.disabled=true;$('teacherShareUrl').value='';$('copyTeacherShareUrl').disabled=true;$('teacherShareFeedback').textContent='جارٍ تجهيز رابط المشاهدة…';$('teacherLinkFeedback').textContent='جارٍ تجهيز الرابط…';$('teacherShareDialog').showModal();try{$('teacherShareUrl').value=await prepareTeacherLink();$('copyTeacherShareUrl').disabled=false;$('teacherShareFeedback').textContent='اضغط نسخ الرابط لإرساله للمعلمين';if($('teacherShareDialog').open)await copyPreparedTeacherLink()}catch(error){$('teacherShareFeedback').textContent=error.name==='AbortError'?'تعذر الاتصال؛ أعد المحاولة':error.message;$('teacherLinkFeedback').textContent=$('teacherShareFeedback').textContent}finally{button.disabled=false}};
$('copyTeacherShareUrl').onclick=()=>void copyPreparedTeacherLink();
$('teacherShareUrl').onclick=()=>{$('teacherShareUrl').select();$('teacherShareUrl').setSelectionRange(0,$('teacherShareUrl').value.length)};
$('closeTeacherShare').onclick=()=>$('teacherShareDialog').close();
void prepareTeacherLink().catch(()=>{});

async function downloadDailyReports(format){
 const button=$(format==='word'?'downloadDailyReportsWord':'downloadDailyReports'),feedback=$('teacherReportFeedback'),date=$('teacherReportDate').value,school=$('teacherReportSchool').value.trim();
 bulkReportsBusy=true;button.disabled=true;try{
  if($('teacherReportScope').value==='today'&&date!==model.day()){updateReportReadiness();throw new Error('بدأ يوم جديد؛ اعرض خطابات اليوم الجديد أولًا')}if(!/^\d{4}-\d{2}-\d{2}$/.test(date))throw new Error('حدد تاريخ الخطابات');
  feedback.textContent='جارٍ تجهيز خطابات '+date+' للإرسال…';
  const data=await day(date,true);teacherReportDay=data;const reports=availableLetters(data).sort((a,b)=>a.name.localeCompare(b.name,'ar'));
  if(!reports.length)throw new Error('لا توجد خطابات مستحقة لهذا اليوم · '+date);
  const files={};for(let i=0;i<reports.length;i++){
   feedback.textContent='تجهيز الخطاب '+(i+1)+' من '+reports.length+' · '+reports[i].name;
   const name=reports[i].name.replace(/[\\/:*?"<>|\x00-\x1f]/g,'').trim()||'معلم';
   files[String(i+1).padStart(2,'0')+' - '+name+' - '+date+(format==='word'?'.docx':'.pdf')]=format==='word'?MirsadTeacherReport.documentBytes(reports[i],school,await MirsadTeacherReport.fontBytes()):await MirsadTeacherReportPdf.documentBytes(reports[i],school);
  }
  const bytes=MirsadTeacherReport.zip(files),url=URL.createObjectURL(new Blob([bytes],{type:'application/zip'})),link=document.createElement('a');
  link.href=url;link.download='خطابات المعلمين - '+date+' - '+(format==='word'?'Word':'PDF')+'.zip';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);
  feedback.textContent='تم تجهيز '+reports.length+' خطابًا ليوم '+date+' في ملف واحد؛ كل معلم له خطاب '+(format==='word'?'Word':'PDF')+' مستقل.';
 }catch(error){feedback.textContent=error.message}finally{bulkReportsBusy=false;updateReportReadiness()}
}
$('downloadDailyReports').onclick=()=>downloadDailyReports('pdf');
$('downloadDailyReportsWord').onclick=()=>downloadDailyReports('word');
updateReportReadiness();


window.addEventListener("mirsad-schedule-adopted",()=>{cache.clear();renderedDays.clear();void refreshRemote()});
